const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞（示意）' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '液泡' },
      { kind: 'text', payload: '细胞核' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var M = metrics || [];
    function mw(i) {
      var t = M[i];
      if (t && typeof t.width === 'number' && t.width > 0) return t.width;
      return 0;
    }
    var minWH = Math.min(W, H);
    var fsLabel = Math.max(11, Math.min(18, minWH * 0.03));
    var fsTitle = Math.max(12, Math.min(21, minWH * 0.035));

    function roundRectPts(x0, y0, x1, y1, r, seg) {
      var pts = [], i, a;
      seg = seg || 10;
      function corner(ccx, ccy, a0, a1) {
        for (i = 0; i <= seg; i++) {
          a = a0 + (a1 - a0) * (i / seg);
          pts.push([ccx + Math.cos(a) * r, ccy + Math.sin(a) * r]);
        }
      }
      corner(x0 + r, y0 + r, Math.PI, Math.PI * 1.5);
      corner(x1 - r, y0 + r, Math.PI * 1.5, Math.PI * 2);
      corner(x1 - r, y1 - r, 0, Math.PI * 0.5);
      corner(x0 + r, y1 - r, Math.PI * 0.5, Math.PI);
      pts.push([pts[0][0], pts[0][1]]);
      return pts;
    }

    function superEllipsePts(ccx, ccy, rx, ry, n, p) {
      var pts = [], i, a, c, s;
      n = n || 96;
      for (i = 0; i < n; i++) {
        a = Math.PI * 2 * i / n;
        c = Math.cos(a);
        s = Math.sin(a);
        pts.push([
          ccx + rx * (c >= 0 ? 1 : -1) * Math.pow(Math.abs(c), 2 / p),
          ccy + ry * (s >= 0 ? 1 : -1) * Math.pow(Math.abs(s), 2 / p)
        ]);
      }
      pts.push([pts[0][0], pts[0][1]]);
      return pts;
    }

    function arrowTri(x1, y1, x2, y2, len, ang) {
      var dx = x2 - x1, dy = y2 - y1;
      var L = Math.sqrt(dx * dx + dy * dy) || 1;
      var back = Math.atan2(-dy / L, -dx / L);
      var p1 = [x2 + len * Math.cos(back - ang), y2 + len * Math.sin(back - ang)];
      var p2 = [x2 + len * Math.cos(back + ang), y2 + len * Math.sin(back + ang)];
      return [p1, [x2, y2], p2, p1];
    }

    var x0 = W * 0.10, y0 = H * 0.20, x1 = W * 0.90, y1 = H * 0.92;
    var rad = minWH * 0.03;
    var inset = minWH * 0.022;
    var wallPts = roundRectPts(x0, y0, x1, y1, rad);
    var membPts = roundRectPts(x0 + inset, y0 + inset, x1 - inset, y1 - inset, rad * 0.8);

    var vacCx = W * 0.44, vacCy = H * 0.55;
    var vacRx = W * 0.20, vacRy = H * 0.215;
    var vacPts = superEllipsePts(vacCx, vacCy, vacRx, vacRy, 96, 2.4);

    var nucCx = W * 0.765, nucCy = H * 0.52, nucR = minWH * 0.085;

    var hLen = minWH * 0.022, hAng = 0.42;
    var w1 = [W * 0.30, H * 0.135], w2 = [W * 0.30, H * 0.19];
    var v1 = [W * 0.215, H * 0.845], v2 = [W * 0.289, H * 0.715];
    var n1 = [W * 0.80, H * 0.825], n2 = [nucCx + nucR * 0.45, nucCy + nucR * 0.89];

    var paths = [
      { id: 'wallFill', commands: visualSdk.polyline(wallPts) },
      { id: 'membrane', commands: visualSdk.polyline(membPts) },
      { id: 'vacuole', commands: visualSdk.polyline(vacPts) },
      { id: 'nucleus', commands: visualSdk.circle(nucCx, nucCy, nucR) },
      { id: 'nucleolus', commands: visualSdk.circle(nucCx + nucR * 0.28, nucCy - nucR * 0.22, nucR * 0.32) },
      { id: 'lead1', commands: visualSdk.polyline([w1, w2]) },
      { id: 'head1', commands: visualSdk.polyline(arrowTri(w1[0], w1[1], w2[0], w2[1], hLen, hAng)) },
      { id: 'lead2', commands: visualSdk.polyline([v1, v2]) },
      { id: 'head2', commands: visualSdk.polyline(arrowTri(v1[0], v1[1], v2[0], v2[1], hLen, hAng)) },
      { id: 'lead3', commands: visualSdk.polyline([n1, n2]) },
      { id: 'head3', commands: visualSdk.polyline(arrowTri(n1[0], n1[1], n2[0], n2[1], hLen, hAng)) }
    ];

    var labVacX = W * 0.185;
    if (mw(2) > 0) labVacX = Math.max(labVacX, mw(2) / 2 + minWH * 0.02);
    var labWallX = W * 0.30;
    var labNucX = W * 0.80;

    var ink = '#2b3a22';
    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'wallFill', fill: '#f4f8ec', stroke: '#7d8f5e', strokeWidth: Math.max(2, minWH * 0.006) },
        { type: 'path', pathId: 'membrane', fill: 'none', stroke: '#a8bd8c', strokeWidth: Math.max(1, minWH * 0.0035) },
        { type: 'path', pathId: 'vacuole', fill: '#dbedf1', stroke: '#7fb2b8', strokeWidth: Math.max(1.5, minWH * 0.004) },
        { type: 'path', pathId: 'nucleus', fill: '#f7e4cb', stroke: '#c08a52', strokeWidth: Math.max(1.5, minWH * 0.004) },
        { type: 'path', pathId: 'nucleolus', fill: '#dcae74', stroke: '#b8834a', strokeWidth: Math.max(1, minWH * 0.003) },
        { type: 'path', pathId: 'lead1', fill: 'none', stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'path', pathId: 'head1', fill: ink, stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'path', pathId: 'lead2', fill: 'none', stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'path', pathId: 'head2', fill: ink, stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'path', pathId: 'lead3', fill: 'none', stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'path', pathId: 'head3', fill: ink, stroke: ink, strokeWidth: Math.max(1, minWH * 0.0028) },
        { type: 'label', text: '植物细胞（示意）', x: W * 0.5, y: H * 0.06, fontSize: fsTitle, fill: ink, align: 'center', baseline: 'middle' },
        { type: 'label', text: '细胞壁', x: labWallX, y: H * 0.105, fontSize: fsLabel, fill: ink, align: 'center', baseline: 'middle' },
        { type: 'label', text: '液泡', x: labVacX, y: H * 0.855, fontSize: fsLabel, fill: ink, align: 'center', baseline: 'middle' },
        { type: 'label', text: '细胞核', x: labNucX, y: H * 0.855, fontSize: fsLabel, fill: ink, align: 'center', baseline: 'middle' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
